/**
 * The contract `tooltip.tsx` (native) and `tooltip.web.tsx` (radix) both
 * implement. Its own module because Metro resolves `./tooltip` to
 * `tooltip.web.tsx` on web.
 *
 * The web half takes radix's props on top of this — `open`/`onOpenChange` on
 * `Tooltip`, `sideOffset`/`align`/`hidden` on the content, the trigger's
 * `<button>` attributes — as shadcn's `tooltip` does, so a DOM call site ports
 * unchanged. Those extras are web only.
 */
import { Children, isValidElement, type ReactNode } from "react";

export type TooltipProviderProps = {
  /** Hover time before a tooltip opens, in ms. Web only — see `tooltip.tsx`. */
  delayDuration?: number | undefined;
  /** Grace period during which a neighbouring tooltip opens instantly. Web only. */
  skipDelayDuration?: number | undefined;
  children: ReactNode;
};

/** Which edge of the trigger the bubble sits on. */
export type TooltipSide = "top" | "right" | "bottom" | "left";

export type TooltipProps = { children: ReactNode };

export type TooltipTriggerProps = {
  /** Hand the handlers to the single child rather than wrapping it. */
  asChild?: boolean | undefined;
  /** The wrapper's class, when not `asChild`. */
  className?: string | undefined;
  children: ReactNode;
};

export type TooltipContentProps = {
  side?: TooltipSide | undefined;
  className?: string | undefined;
  children: ReactNode;
};

/**
 * The tooltip's bubble: the page's colours swapped, so it stands apart from whatever it floats over.
 * It was `bg-secondary`, a raised surface, which in light is all but the page's own white: with
 * only a `/10` edge it melted into the row under it and read as see-through. `foreground` on
 * `background` is the page's own text contrast, in every palette.
 *
 * `max-w-xs`, so a long hint wraps into a short paragraph rather than running the width of the
 * screen in one line (#486).
 */
export const TOOLTIP_CONTENT_CLASS =
  "max-w-xs overflow-hidden rounded-md bg-foreground px-3 py-1.5 shadow-md";
/** The type of the tooltip's text: the page's background colour, on the swapped bubble. */
export const TOOLTIP_TEXT_CLASS = "text-sm text-background";

/**
 * Where the bubble goes on native, per side, when there is no layer to draw it in (no `OverlayHost`
 * or `ToastProvider` at the app's root): beside the trigger in the trigger's parent. There it is
 * clipped by a `ScrollView` around the trigger, takes no more room than the trigger has, and is not
 * kept on screen; {@link placeTooltip} is what a layer does instead.
 */
export const TOOLTIP_SIDE_CLASS = {
  top: "bottom-full mb-1 self-center",
  bottom: "top-full mt-1 self-center",
  left: "right-full mr-1 self-start",
  right: "left-full ml-1 self-start",
} as const satisfies Record<TooltipSide, string>;

/** A box in a layer: where the trigger is in the window, less where the layer is. */
export type TooltipBox = { x: number; y: number; width: number; height: number };

/** A width and a height: the bubble's own, or the layer's. */
export type TooltipSize = { width: number; height: number };

/** The gap between a device's bubble and its trigger, `mb-1` in {@link TOOLTIP_SIDE_CLASS}. */
export const TOOLTIP_GAP = 4;
/** How far a device's bubble keeps from the screen's edges, the web's `collisionPadding`. */
export const TOOLTIP_EDGE = 8;

const OPPOSITE = {
  top: "bottom",
  bottom: "top",
  left: "right",
  right: "left",
} as const satisfies Record<TooltipSide, TooltipSide>;

const HALF = 2;

/** `value`, moved into `[low, high]`; `low` when the range is empty. */
function clamp(value: number, low: number, high: number): number {
  return Math.max(low, Math.min(value, high));
}

/**
 * Where a device's bubble goes in its layer: on `side` of the trigger and centred on it, on the
 * other side when `side` has no room and the other has, and slid along to stay
 * {@link TOOLTIP_EDGE} clear of the screen's edges, as radix places the web's.
 */
export function placeTooltip(
  trigger: TooltipBox,
  bubble: TooltipSize,
  room: TooltipSize,
  side: TooltipSide,
): { x: number; y: number; side: TooltipSide } {
  const fits: Record<TooltipSide, boolean> = {
    top: trigger.y - TOOLTIP_GAP - bubble.height >= TOOLTIP_EDGE,
    bottom: trigger.y + trigger.height + TOOLTIP_GAP + bubble.height <= room.height - TOOLTIP_EDGE,
    left: trigger.x - TOOLTIP_GAP - bubble.width >= TOOLTIP_EDGE,
    right: trigger.x + trigger.width + TOOLTIP_GAP + bubble.width <= room.width - TOOLTIP_EDGE,
  };
  const chosen = fits[side] || fits[OPPOSITE[side]] === false ? side : OPPOSITE[side];
  const centreX = trigger.x + (trigger.width - bubble.width) / HALF;
  const centreY = trigger.y + (trigger.height - bubble.height) / HALF;
  const at = {
    top: { x: centreX, y: trigger.y - TOOLTIP_GAP - bubble.height },
    bottom: { x: centreX, y: trigger.y + trigger.height + TOOLTIP_GAP },
    left: { x: trigger.x - TOOLTIP_GAP - bubble.width, y: centreY },
    right: { x: trigger.x + trigger.width + TOOLTIP_GAP, y: centreY },
  }[chosen];
  return {
    x: clamp(at.x, TOOLTIP_EDGE, room.width - TOOLTIP_EDGE - bubble.width),
    y: clamp(at.y, TOOLTIP_EDGE, room.height - TOOLTIP_EDGE - bubble.height),
    side: chosen,
  };
}

/** The least time a device's bubble stays up after the finger lifts: long enough for a word. */
const MIN_VISIBLE_MS = 2500;
/**
 * The time a character adds: 60ms is about 170 words a minute, a slow reading pace, so a reader who
 * takes longer than most still reaches the end of a long hint (WCAG 2.2.1).
 */
const MS_PER_CHARACTER = 60;

/** How many characters of text a node holds, through any elements it is made of. */
function textLength(node: ReactNode): number {
  let length = 0;
  Children.forEach(node, (child) => {
    if (typeof child === "string" || typeof child === "number") {
      length += String(child).length;
    } else if (isValidElement<{ children?: ReactNode }>(child)) {
      length += textLength(child.props.children);
    }
  });
  return length;
}

/**
 * How long a device's tooltip stays up once the finger lifts: longer for a longer hint, and never
 * less than {@link MIN_VISIBLE_MS}. The web's stays while it is hovered or focused, and needs none.
 */
export function tooltipVisibleMs(content: ReactNode): number {
  return Math.max(MIN_VISIBLE_MS, textLength(content) * MS_PER_CHARACTER);
}

/**
 * The native tooltip: long-press the trigger and the bubble appears above it,
 * for a time that grows with its text and starts again when the finger lifts.
 *
 * Hover does not exist on a touch screen, so radix's trigger has no direct
 * equivalent — but dropping the content entirely would lose the only place
 * some labels are written down. Long-press is the platform's own convention
 * for "tell me more about this control", and it costs no dependency.
 *
 * There is no wrapper around the trigger, as there is none on web, where radix's
 * root is a fragment. A `View` around it took the trigger's place in its parent,
 * so the trigger's own `absolute top-2 right-2` or `ml-auto` placed it inside the
 * wrapper rather than in the row (#423), and every icon `Button` has a tooltip.
 *
 * The bubble is drawn in the top overlay layer (`@cubeui/overlay`), placed against the trigger as
 * both are measured in the window. Drawn beside the trigger in its parent, it was clipped by any
 * `ScrollView` around it, the top bar's places and a folded sidebar's rows, and it had only the
 * trigger's width to wrap in: a long hint stood a word to a line (#509). With no layer — no
 * `OverlayHost` or `ToastProvider` at the root — it is still drawn there, as before.
 */

import {
  cloneElement,
  createContext,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  type RefObject,
  useContext,
  useEffect,
  useRef,
  useState,
} from "react";
import { type LayoutChangeEvent, type LayoutRectangle, Pressable, Text, View } from "react-native";
import { OverlayPortal, useTopLayer } from "@/components/ui/overlay";
import {
  placeTooltip,
  TOOLTIP_CONTENT_CLASS,
  TOOLTIP_EDGE,
  TOOLTIP_SIDE_CLASS,
  TOOLTIP_TEXT_CLASS,
  type TooltipBox,
  type TooltipContentProps,
  type TooltipProps,
  type TooltipProviderProps,
  type TooltipSide,
  type TooltipSize,
  type TooltipTriggerProps,
  tooltipVisibleMs,
} from "@/components/ui/tooltip-base";
import { addHandlers, cn } from "@/lib/utils";

type TooltipState = {
  open: boolean;
  setOpen: (open: boolean) => void;
  /**
   * Where the trigger was last laid out in its parent, for a bubble with no layer to go in. A ref,
   * not state: every icon button has a tooltip, and a render per button per layout is paid for a
   * bubble that is rarely opened.
   */
  frame: RefObject<LayoutRectangle | null>;
  /** The trigger's element, measured in the window when the bubble opens. */
  node: { current: unknown };
  /** Counts the releases of an open bubble's trigger, so its clock starts again from each. */
  released: number;
  release: () => void;
};

const TooltipContext = createContext<TooltipState>({
  open: false,
  setOpen: () => {},
  frame: { current: null },
  node: { current: null },
  released: 0,
  release: () => {},
});

/**
 * Nothing to provide on native; kept so call sites need not branch.
 *
 * `delayDuration` and `skipDelayDuration` are accepted and ignored. They describe
 * hover timing, and there is no hover here — the delay a touch user experiences is
 * the long press itself, which the platform already times.
 */
function TooltipProvider({ children }: TooltipProviderProps) {
  return children;
}

/** The root of a tooltip: it holds the open state. */
function Tooltip({ children }: TooltipProps) {
  const [open, setOpen] = useState(false);
  const [released, setReleased] = useState(0);
  const frame = useRef<LayoutRectangle | null>(null);
  const node = useRef<unknown>(null);
  const release = () => setReleased((count) => count + 1);
  return (
    <TooltipContext.Provider value={{ open, setOpen, frame, node, released, release }}>
      {children}
    </TooltipContext.Provider>
  );
}

/**
 * The element the tooltip describes: hovered or focused on the web, long-pressed on device.
 *
 * With `asChild` the child is handed a `ref`, `onLongPress`, `onPressOut` and `onLayout`, and puts
 * them on the element it draws, as a `Pressable` and a `Button` do. Without the `ref` the bubble is
 * drawn beside the trigger in its parent, where a `ScrollView` clips it; without `onLayout` as well
 * it is not drawn; without `onPressOut` its clock runs from the long press alone.
 */
function TooltipTrigger({ asChild, className, children }: TooltipTriggerProps) {
  const { open, setOpen, frame, node, release } = useContext(TooltipContext);
  const show = () => setOpen(true);
  const lift = () => {
    if (open) {
      release();
    }
  };
  const measure = (event: LayoutChangeEvent) => {
    frame.current = event.nativeEvent.layout;
  };
  if (asChild && isValidElement(children)) {
    // The child's own ref still gets the element; the tooltip only needs to read it too.
    const own = (children.props as { ref?: Ref<unknown> }).ref;
    const handled = addHandlers(children, {
      onLongPress: show,
      onPressOut: lift,
      onLayout: measure,
    });
    return cloneElement(handled as ReactElement<{ ref?: Ref<unknown> }>, {
      ref: (element: unknown) => {
        node.current = element;
        if (typeof own === "function") {
          own(element);
        } else if (own) {
          own.current = element;
        }
      },
    });
  }
  return (
    <Pressable
      ref={(element) => {
        node.current = element;
      }}
      onLongPress={show}
      onPressOut={lift}
      onLayout={measure}
      className={cn(className)}
    >
      {children}
    </Pressable>
  );
}

/** An element React Native can measure in the window: a host view on device and under the web. */
type Measurable = {
  measureInWindow: (done: (x: number, y: number, width: number, height: number) => void) => void;
};

function isMeasurable(element: unknown): element is Measurable {
  return (
    typeof element === "object" &&
    element !== null &&
    typeof (element as Partial<Measurable>).measureInWindow === "function"
  );
}

/** Where the trigger is in the layer, and how big the layer is. */
type Anchor = { trigger: TooltipBox; room: TooltipSize };

/** The tooltip's bubble and its text. */
function TooltipContent({ side = "top", className, children }: TooltipContentProps) {
  const { open, setOpen, frame, node, released } = useContext(TooltipContext);
  const layer = useTopLayer();
  const [anchor, setAnchor] = useState<Anchor | null>(null);
  // A fixed 2.5s took a long hint away mid-sentence (WCAG 2.2.1), so the time grows with the text.
  // The clock runs from the long press and starts again when the finger lifts. It does not wait
  // for the lift: a release that never arrives (react-native-web drops one after a hold of a few
  // seconds) would leave the bubble up for good.
  const visibleMs = tooltipVisibleMs(children);

  // `released` is what restarts the clock; the effect does not read it.
  // biome-ignore lint/correctness/useExhaustiveDependencies: runs again on each release
  useEffect(() => {
    if (open === false) {
      return;
    }
    const timer = setTimeout(() => setOpen(false), visibleMs);
    return () => clearTimeout(timer);
  }, [open, setOpen, visibleMs, released]);

  // Both are measured in the window, and the trigger placed by the difference: a layer at the root
  // of an app laid out under a status bar does not start at the window's corner.
  useEffect(() => {
    const trigger = node.current;
    const box = layer?.node.current;
    if (open === false || isMeasurable(trigger) === false || isMeasurable(box) === false) {
      setAnchor(null);
      return;
    }
    let current = true;
    trigger.measureInWindow((x, y, width, height) => {
      box.measureInWindow((left, top, roomWidth, roomHeight) => {
        if (current) {
          setAnchor({
            trigger: { x: x - left, y: y - top, width, height },
            room: { width: roomWidth, height: roomHeight },
          });
        }
      });
    });
    return () => {
      current = false;
    };
  }, [open, layer, node]);

  if (open === false) {
    return null;
  }
  if (layer !== null && isMeasurable(node.current)) {
    return anchor === null ? null : (
      <OverlayPortal layer={layer}>
        <PlacedBubble anchor={anchor} side={side} className={className}>
          {children}
        </PlacedBubble>
      </OverlayPortal>
    );
  }
  return (
    <BesideTrigger frame={frame.current} side={side} className={className}>
      {children}
    </BesideTrigger>
  );
}

type BubbleProps = { side: TooltipSide; className: string | undefined; children: ReactNode };

/**
 * The bubble in a layer. It is laid out first in a row the width of the screen less its edges, so
 * it takes its own width up to `max-w-xs` rather than the trigger's, and is hidden until that is
 * known; then it is moved into place, by a transform so its width does not change with where it
 * goes.
 */
function PlacedBubble({ anchor, side, className, children }: BubbleProps & { anchor: Anchor }) {
  const [size, setSize] = useState<TooltipSize | null>(null);
  const place = size === null ? null : placeTooltip(anchor.trigger, size, anchor.room, side);
  return (
    <View
      className="absolute top-0 items-start"
      style={{ left: TOOLTIP_EDGE, right: TOOLTIP_EDGE, pointerEvents: "none" }}
    >
      <View
        role="tooltip"
        onLayout={(event) => {
          const { width, height } = event.nativeEvent.layout;
          setSize({ width, height });
        }}
        className={cn(TOOLTIP_CONTENT_CLASS, className)}
        style={
          place === null
            ? { opacity: 0 }
            : { transform: [{ translateX: place.x - TOOLTIP_EDGE }, { translateY: place.y }] }
        }
      >
        <Text className={TOOLTIP_TEXT_CLASS}>{children}</Text>
      </View>
    </View>
  );
}

/**
 * The bubble with no layer: a box over the trigger, in the trigger's parent, so the side classes
 * place the bubble against the trigger. A layout's position counts the parent's border and an
 * absolute one starts inside it, so a bordered parent moves the bubble by that border.
 */
function BesideTrigger({
  frame,
  side,
  className,
  children,
}: BubbleProps & { frame: LayoutRectangle | null }) {
  if (frame === null) {
    return null;
  }
  return (
    <View
      className="absolute z-50"
      style={{
        left: frame.x,
        top: frame.y,
        width: frame.width,
        height: frame.height,
        pointerEvents: "none",
      }}
    >
      <View
        role="tooltip"
        className={cn("absolute", TOOLTIP_SIDE_CLASS[side], TOOLTIP_CONTENT_CLASS, className)}
      >
        <Text className={TOOLTIP_TEXT_CLASS}>{children}</Text>
      </View>
    </View>
  );
}

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger };

/**
 * The web tooltip: radix, shown on hover and focus. `tooltip.tsx` is the
 * native counterpart and `tooltip-base.ts` holds the contract they share.
 *
 * Every part also takes the props of the radix part it renders, as shadcn's
 * `tooltip` does — `open`/`onOpenChange`/`delayDuration` on `Tooltip`,
 * `sideOffset`/`align` on the content — so a DOM call site ports unchanged.
 */

import { Tooltip as TooltipPrimitive } from "radix-ui";
import type * as React from "react";
import { createContext, useContext } from "react";
import {
  TOOLTIP_CONTENT_CLASS,
  TOOLTIP_TEXT_CLASS,
  type TooltipContentProps,
  type TooltipProps,
  type TooltipProviderProps,
  type TooltipTriggerProps,
} from "@/components/ui/tooltip-base";
import { cn } from "@/lib/utils";

/** The shared contract, widened to what the radix part underneath accepts. */
type Wide<Base, Radix> = Base & Omit<Radix, keyof Base>;

/** Whether a `TooltipProvider` is above. Radix throws without one and has no way to ask. */
const ProvidedContext = createContext(false);

// `delayDuration` defaults to shadcn's `0`, not Radix's 700ms. A tooltip with no provider above
// renders this one, and left to Radix every icon button waited 700ms.
/** Shares the open delay among the tooltips below it. */
function TooltipProvider({
  delayDuration = 0,
  skipDelayDuration,
  ...props
}: Wide<TooltipProviderProps, React.ComponentProps<typeof TooltipPrimitive.Provider>>) {
  return (
    <ProvidedContext.Provider value={true}>
      <TooltipPrimitive.Provider
        {...props}
        delayDuration={delayDuration}
        {...(skipDelayDuration === undefined ? {} : { skipDelayDuration })}
      />
    </ProvidedContext.Provider>
  );
}

/**
 * The root of a tooltip: it holds the open state.
 *
 * It uses the `TooltipProvider` above it, and its timing, when there is one. With none it renders
 * its own, so an installed component can draw a tooltip without the app having set one up.
 */
function Tooltip(props: Wide<TooltipProps, React.ComponentProps<typeof TooltipPrimitive.Root>>) {
  const provided = useContext(ProvidedContext);
  const root = <TooltipPrimitive.Root data-slot="tooltip" {...props} />;
  if (provided) {
    return root;
  }
  return <TooltipProvider>{root}</TooltipProvider>;
}

/** The element the tooltip describes: hovered or focused on the web, long-pressed on device. */
function TooltipTrigger({
  asChild,
  className,
  ...props
}: Wide<TooltipTriggerProps, React.ComponentProps<typeof TooltipPrimitive.Trigger>>) {
  return (
    <TooltipPrimitive.Trigger
      data-slot="tooltip-trigger"
      asChild={asChild ?? false}
      {...(className === undefined ? {} : { className })}
      {...props}
    />
  );
}

/** Kept clear of the window's edge, where radix would otherwise slide the bubble flush with it. */
const COLLISION_PADDING = 8;

/** The tooltip's bubble and its text. */
function TooltipContent({
  side = "top",
  sideOffset = 4,
  collisionPadding = COLLISION_PADDING,
  className,
  children,
  ...props
}: Wide<TooltipContentProps, React.ComponentProps<typeof TooltipPrimitive.Content>>) {
  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Content
        data-slot="tooltip-content"
        side={side}
        sideOffset={sideOffset}
        collisionPadding={collisionPadding}
        className={cn(
          // `text-balance` evens the lines of a hint that wraps, so the last is not one word.
          "z-50 text-balance animate-in fade-in-0 zoom-in-95 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2",
          TOOLTIP_CONTENT_CLASS,
          TOOLTIP_TEXT_CLASS,
          className,
        )}
        {...props}
      >
        {children}
      </TooltipPrimitive.Content>
    </TooltipPrimitive.Portal>
  );
}

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger };
